  "test": "from types import SimpleNamespace

import pytest

from langfuse.span_filter import is_app_root_eligible


def _make_span(*, scope_name: str, name: str, has_parent: bool = True):
    scope = SimpleNamespace(name=scope_name)
    parent = SimpleNamespace() if has_parent else None
    return SimpleNamespace(
        parent=parent,
        instrumentation_scope=scope,
        name=name,
        attributes=None,
    )


def test_litellm_response_span_is_not_app_root():
    span = _make_span(scope_name="litellm", name="raw_gen_ai_response")
    assert is_app_root_eligible(span) is False


def test_litellm_request_span_still_app_root_allowed_when_no_parent():
    # No parent -> eligible regardless of name
    span = _make_span(scope_name="litellm", name="raw_gen_ai_request", has_parent=False)
    assert is_app_root_eligible(span) is True


def test_other_span_is_app_root():
    span = _make_span(scope_name="some.scope", name="some.operation")
    assert is_app_root_eligible(span) is True"
}
